import{_ as o,C as s,o as d,c as e,j as i,a as l,E as t,a2 as r}from"./chunks/framework.C21TwvGF.js";const A=JSON.parse(`{"title":"1-dars (Mentor). UX va UI dizayn tushunchalari: nima va nima uchun","description":"","frontmatter":{"title":"1-dars (Mentor). UX va UI dizayn tushunchalari: nima va nima uchun","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"9-sinf (UX/UI)","link":"/mentor/9-sinf/"},"week":{"n":1,"link":"/mentor/9-sinf/hafta-01/"},"g":1,"title":"UX va UI dizayn tushunchalari: nima va nima uchun","lead":"Har kuni Telegram, Instagram yoki o'yinlarni ochasiz, lekin ularning ko'rinishi va qulayligi ortida kimdir turganini o'ylab ko'rganmisiz? Bugun siz ikkita sirli qisqartma, UX va UI, ni ajratishni o'rganasiz va ilovalarga dizayner ko'zi bilan qaraysiz.","slide":"/slaydlar/9-sinf/hafta-01/dars-1.html","test":"/slaydlar/9-sinf/hafta-01/dars-1-test.html","student_link":"/9-sinf/hafta-01/dars-1","tabs":[{"g":1,"link":"/mentor/9-sinf/hafta-01/dars-1","current":true},{"g":2,"link":"/mentor/9-sinf/hafta-01/dars-2","current":false},{"g":3,"link":"/mentor/9-sinf/hafta-01/dars-3","current":false}],"prev":null,"next":{"g":2,"title":"UX/UI dizayn tamoyillari va jarayoni: yaxshi dizayn qanday bo'ladi","link":"/mentor/9-sinf/hafta-01/dars-2"}}},"headers":[],"relativePath":"mentor/9-sinf/hafta-01/dars-1.md","filePath":"mentor/9-sinf/hafta-01/dars-1.md"}`),h={name:"mentor/9-sinf/hafta-01/dars-1.md"},m={class:"blk"},u={id:"_1-dars-rejasi",tabindex:"-1"},y={class:"blk"},g={id:"_2-konspekt",tabindex:"-1"},b={class:"blk"},q={id:"_3-misollar-kod-o-rniga",tabindex:"-1"},k={class:"blk"},v={id:"_4-amaliy-topshiriqlar",tabindex:"-1"},U={class:"blk"},f={id:"_5-tezkor-nazorat",tabindex:"-1"},z={class:"blk"},p={id:"_6-uyga-vazifa",tabindex:"-1"},x={class:"blk"},I={id:"_7-mentor-uchun-eslatmalar",tabindex:"-1"};function c(X,a,_,T,j,P){const n=s("Icon");return d(),e("div",null,[a[24]||(a[24]=i("p",null,[i("strong",null,"Hafta:"),l(" 1 · "),i("strong",null,"Davomiyligi:"),l(" 80 daqiqa · "),i("strong",null,"Turi:"),l(" nazariya + amaliyot (qog'ozda) · "),i("strong",null,"I-bob"),l(", 1-dars")],-1)),a[25]||(a[25]=i("blockquote",null,[i("p",null,"Dasturda «UX va UI dizayn tushunchalari» mavzusiga 2 dars ajratilgan (1–2). Bo'linish: 1-dars — UX nima, UI nima, farqi, dizaynerlar qayerda ishlaydi va nega muhim; 2-dars — UX/UI tamoyillari (4C, UX tamoyillari), yaxshi va yomon dizayn, wireframe / mockup / prototip bosqichlari. 3-dars — foydalanuvchi tadqiqoti. Manba: o'quv qo'llanma, 1.1-bo'lim («UX va UI dizayn tushunchalari»), 1.1-jadval. Dars birinchi bo'lgani uchun kurs xaritasi bilan tanishtirish ham bor.")],-1)),i("div",m,[i("h2",u,[t(n,{name:"file-text"}),a[0]||(a[0]=l(" 1. Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#_1-dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> 1. Dars rejasi"'},"​",-1))]),a[2]||(a[2]=r('<p><strong>Maqsad:</strong> o&#39;quvchi UX va UI nima ekanini o&#39;z so&#39;zi bilan tushuntiradi, ikkalasini farqlaydi va real ilovadan misol bilan ko&#39;rsatadi.</p><p><strong>Kutiladigan natija:</strong></p><ul><li>UX (User Experience) — foydalanuvchi tajribasi, UI (User Interface) — foydalanuvchi interfeysi ekanini biladi.</li><li>Jadval bo&#39;yicha farqni (tashqi ko&#39;rinish va umumiy tajriba) ayta oladi.</li><li>UX dizayner va UI dizaynerning asosiy ishlarini sanaydi.</li><li>UX/UI dizayn qayerlarda qo&#39;llanishini (veb-sayt, mobil ilova, dashboard, aqlli qurilma) biladi.</li><li>Yaxshi UX/UI nega kerakligini (mamnunlik, raqobat, brendga ishonch) tushuntiradi.</li></ul><table tabindex="0"><thead><tr><th>Vaqt</th><th>Bosqich</th><th>Mazmun</th></tr></thead><tbody><tr><td>0–10</td><td>Kirish</td><td>Tanishuv, kurs xaritasi, «sizni eng ko&#39;p g&#39;azablantirgan ilova» savoli</td></tr><tr><td>10–25</td><td>Yangi mavzu 1</td><td>UX nima, UX dizayner nima qiladi</td></tr><tr><td>25–35</td><td>Yangi mavzu 2</td><td>UI nima, UI dizayner nima qiladi</td></tr><tr><td>35–40</td><td>Tanaffus</td><td></td></tr><tr><td>40–52</td><td>Yangi mavzu 3</td><td>Farq, o&#39;zaro bog&#39;liqlik, qayerda ishlanadi, nega muhim</td></tr><tr><td>52–75</td><td>Amaliyot</td><td>Telegram/Instagram tahlili va qog&#39;ozda dizayn</td></tr><tr><td>75–80</td><td>Tezkor nazorat va xulosa</td><td></td></tr></tbody></table>',4))]),i("div",y,[i("h2",g,[t(n,{name:"file-text"}),a[3]||(a[3]=l(" 2. Konspekt ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#_2-konspekt","aria-label":'Permalink to "<Icon name="file-text" /> 2. Konspekt"'},"​",-1))]),a[5]||(a[5]=r('<h3 id="_2-1-kirish-10-daqiqa" tabindex="-1">2.1. Kirish (10 daqiqa) <a class="header-anchor" href="#_2-1-kirish-10-daqiqa" aria-label="Permalink to &quot;2.1. Kirish (10 daqiqa)&quot;">​</a></h3><p>Birinchi dars: tanishuv va kurs xaritasi (nazariya → wireframe → Figma va boshqa vositalar → HTML/CSS/JS → React). Keyin savol: «Qaysi ilova yoki sayt sizni g&#39;azablantirgan? Nega?» 3–4 o&#39;quvchi javob beradi. Ularning javoblari («tugma topolmadim», «juda sekin», «hamma narsa chalkash») bugungi mavzuning o&#39;zi ekanini ayting: «Siz hozir UX muammolarini sanadingiz».</p><h3 id="_2-2-ux-nima-15-daqiqa" tabindex="-1">2.2. UX nima? (15 daqiqa) <a class="header-anchor" href="#_2-2-ux-nima-15-daqiqa" aria-label="Permalink to &quot;2.2. UX nima? (15 daqiqa)&quot;">​</a></h3><p><strong>UX (User Experience) — foydalanuvchi tajribasi.</strong> Qo&#39;llanma ta&#39;rifi: foydalanuvchining interfeys bilan ishlash tajribasi va taassuroti. U maqsadiga erisha oladimi va buni bajarish qanchalik oddiy yoki murakkab ekanini belgilaydi.</p><p>O&#39;xshatish — <strong>eshik</strong>: chiroyli eshik, lekin «tortish» kerakmi yoki «itarish»? Odam eshik oldida turib qolsa, bu UX muammosi (eshik chiroyli bo&#39;lsa ham).</p><p>UX savoli: <strong>«Bu mahsulot foydalanuvchi uchun qanchalik qulay?»</strong></p><p>UX dizayner (qo&#39;llanma bo&#39;yicha):</p><ul><li>foydalanuvchi muammolarini o&#39;rganadi va yechim topadi;</li><li>interfeys qulayligini ta&#39;minlaydi;</li><li>sketch, wireframe va prototiplar yaratadi;</li><li>mahsulotni test qiladi va doimiy takomillashtirib boradi.</li></ul><p>UX ning o&#39;lchovlari: qulaylik, tezlik, hissiy tajriba (jadvaldan). Misol: Telegramda xabar yuborish 2 bosishda bo&#39;ladi. Bu yaxshi UX. Davlat xizmati saytida bitta ma&#39;lumot uchun 7 sahifa ochish — yomon UX.</p><p>Eslatma: UX faqat ekranga tegishli emas. Buyurtma kutish vaqti, qo&#39;ng&#39;iroq markazi, o&#39;ramning ochilishi ham tajribaga kiradi. Biz kursda raqamli mahsulotga e&#39;tibor beramiz.</p><h3 id="_2-3-ui-nima-10-daqiqa" tabindex="-1">2.3. UI nima? (10 daqiqa) <a class="header-anchor" href="#_2-3-ui-nima-10-daqiqa" aria-label="Permalink to &quot;2.3. UI nima? (10 daqiqa)&quot;">​</a></h3><p><strong>UI (User Interface) — foydalanuvchi interfeysi:</strong> mahsulotning qanday ko&#39;rinishi va qanday tuzilishi. Qo&#39;llanma misoli: Google Maps ochganda ko&#39;rgan xarita, tugmalar va menyular. Yaxshi UI da hamma elementlar uyg&#39;un va o&#39;zaro bog&#39;liq bo&#39;ladi.</p><p>UI dizayner (qo&#39;llanma bo&#39;yicha):</p><ul><li>ranglar bilan ishlaydi;</li><li>to&#39;g&#39;ri shriftlarni tanlaydi;</li><li>ikonlar va grafik elementlarni ishlab chiqadi;</li><li>vizual dizaynning umumiy uyg&#39;unligini yaratadi.</li></ul><p>UI savoli: <strong>«Bu mahsulot qanday ko&#39;rinadi va chiroylimi?»</strong> Foydalanuvchi ko&#39;zi bilan ko&#39;radigan hamma narsa — UI.</p><p>UI elementlariga misollar: tugma (button), menyu, matn maydoni (input), ikon, rasm, rang va shrift.</p><h3 id="_2-4-ux-va-ui-farqi-jadval-va-o-zaro-bog-liqlik-12-daqiqa" tabindex="-1">2.4. UX va UI farqi (jadval) va o&#39;zaro bog&#39;liqlik (12 daqiqa) <a class="header-anchor" href="#_2-4-ux-va-ui-farqi-jadval-va-o-zaro-bog-liqlik-12-daqiqa" aria-label="Permalink to &quot;2.4. UX va UI farqi (jadval) va o&#39;zaro bog&#39;liqlik (12 daqiqa)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>UI dizayn</th><th>UX dizayn</th></tr></thead><tbody><tr><td>Tashqi ko&#39;rinishni tayyorlaydi</td><td>Umumiy tajribani shakllantiradi</td></tr><tr><td>Ranglar, tugmalar, shriftlar</td><td>Qulaylik, tezlik, hissiy tajriba</td></tr><tr><td>Ko&#39;zga ko&#39;rinadigan qismlar</td><td>Foydalanuvchining ichki his-tuyg&#39;ulari</td></tr></tbody></table><p>O&#39;xshatishlar:</p><ul><li><strong>Restoran:</strong> UX — kutish vaqti, menyuni tushunish, xizmat; UI — idish, bezak, taom ko&#39;rinishi.</li><li><strong>Uy:</strong> UX — xonalar joylashuvi va eshiklar qulayligi; UI — rang, mebel, parda.</li><li><strong>Avtomobil:</strong> UX — haydash qulayligi; UI — dashbord, tugmalar ko&#39;rinishi.</li></ul><p>Muhim xulosa: <strong>ikkalasi ham kerak va bir-birini to&#39;ldiradi.</strong></p><ul><li>Chiroyli UI + yomon UX = chiroyli, lekin foydalanib bo&#39;lmaydigan ilova (ko&#39;rinishi yaxshi, lekin to&#39;lov tugmasi topilmaydi).</li><li>Yaxshi UX + yomon UI = ishlaydi, lekin ishonch uyg&#39;otmaydi (chalkash ranglar, o&#39;qib bo&#39;lmaydigan shrift).</li><li>Yaxshi UX + yaxshi UI = foydalanuvchi mamnun, qaytib keladi.</li></ul><p><strong>Odatiy xato:</strong> «UX = chiroyli dizayn». Yo&#39;q: chiroylilik UI qismi, UX undan kengroq.</p><h3 id="_2-5-dizaynerlar-qayerda-ishlaydi-qisqa-12-daqiqa-ichida" tabindex="-1">2.5. Dizaynerlar qayerda ishlaydi? (qisqa, 12-daqiqa ichida) <a class="header-anchor" href="#_2-5-dizaynerlar-qayerda-ishlaydi-qisqa-12-daqiqa-ichida" aria-label="Permalink to &quot;2.5. Dizaynerlar qayerda ishlaydi? (qisqa, 12-daqiqa ichida)&quot;">​</a></h3><p>Qo&#39;llanma bo&#39;yicha UX/UI sohasi shu mahsulotlar dizayni va prototipini yaratadi:</p><ul><li>veb-saytlar;</li><li>mobil ilovalar;</li><li>internet platformalar;</li><li>dashboardlar (ma&#39;lumot paneli);</li><li>aqlli qurilmalar;</li><li>boshqa IT-mahsulotlar.</li></ul><p>O&#39;quvchi hayotidan: Telegram, Instagram, o&#39;yinlar, maktab elektron jurnali, Click/Payme kabi ilovalar, aqlli soat. Hamma narsa kimdir dizayn qilgan.</p><h3 id="_2-6-nega-bu-muhim" tabindex="-1">2.6. Nega bu muhim? <a class="header-anchor" href="#_2-6-nega-bu-muhim" aria-label="Permalink to &quot;2.6. Nega bu muhim?&quot;">​</a></h3><p>Qo&#39;llanma xulosasi: samarali UI/UX foydalanuvchi mamnunligini oshiradi, mahsulotning raqobatbardoshligini ta&#39;minlaydi va brendga bo&#39;lgan ishonchni mustahkamlaydi. Oddiy tilda: qulay ilova qoladi, qulay bo&#39;lmasini o&#39;chirib tashlashadi (telefondan ham, xotiradan ham). Bu — dizayner kasbiga talab borligining sababi.</p><p>Eslatma mentorga: aniq ish haqi, bozor statistikasi qo&#39;llanmada yo&#39;q, shuning uchun slaydlarda raqam keltirilmagan. Xohlasangiz mahalliy ish e&#39;lonlaridan o&#39;zingiz misol qo&#39;shing.</p>',30))]),i("div",b,[i("h2",q,[t(n,{name:"file-text"}),a[6]||(a[6]=l(" 3. Misollar (kod o'rniga) ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#_3-misollar-kod-o-rniga","aria-label":`Permalink to "<Icon name="file-text" /> 3. Misollar (kod o'rniga)"`},"​",-1))]),a[8]||(a[8]=i("p",null,[l("Bu darsda kod yo'q. O'rniga ikkita "),i("strong",null,"qog'ozdagi eskiz namunasi"),l(": bir xil UX (bir xil qadamlar), turli UI.")],-1)),a[9]||(a[9]=i("p",null,[i("strong",null,"Namuna: kirish (login) ekrani, UX bir xil: «telefon raqam → Kirish» (2 qadam).")],-1)),a[10]||(a[10]=i("ul",null,[i("li",null,"Variant A (UI): to'q fon, katta ko'k tugma, yumaloq burchaklar."),i("li",null,"Variant B (UI): oq fon, yashil tugma, to'g'ri burchaklar. UX o'zgarmadi (qadamlar bir xil), UI o'zgardi (ko'rinish).")],-1)),a[11]||(a[11]=i("p",null,[i("strong",null,"Namuna: UX ni o'zgartirish."),l(" Variant C: telefon raqam + ism + parol + parolni takrorlash + yosh + shahar → Kirish (6 maydon). UI chiroyli bo'lishi mumkin, lekin UX yomonlashdi.")],-1))]),i("div",k,[i("h2",v,[t(n,{name:"file-text"}),a[12]||(a[12]=l(" 4. Amaliy topshiriqlar ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#_4-amaliy-topshiriqlar","aria-label":'Permalink to "<Icon name="file-text" /> 4. Amaliy topshiriqlar"'},"​",-1))]),a[14]||(a[14]=r('<p>Material: A4 qog&#39;oz, qalam, rangli qalamlar. Kompyuter ixtiyoriy (Figma bepul onlayn, ro&#39;yxatdan o&#39;tishni talab qiladi: mentor hal qiladi; bugun majburiy emas).</p><h3 id="oson-—-ux-yoki-ui" tabindex="-1">Oson — UX yoki UI? <a class="header-anchor" href="#oson-—-ux-yoki-ui" aria-label="Permalink to &quot;Oson — UX yoki UI?&quot;">​</a></h3><p>Ro&#39;yxatdagi har bir gapni UX yoki UI ga ajrating: (1) tugma rangi ko&#39;k; (2) to&#39;lov 2 bosishda bajariladi; (3) shrift «Roboto»; (4) sahifa 1 soniyada ochiladi; (5) ikonlar bir xil uslubda; (6) yangi foydalanuvchi qayerga bosishni tushunadi. <strong>Kutiladigan natija:</strong> to&#39;g&#39;ri ajratilgan 6 ta gap. <strong>Yechim:</strong> (1) UI; (2) UX; (3) UI; (4) UX (tezlik); (5) UI; (6) UX. Eslatma: 4 va 6 ko&#39;rinmaydi, lekin tajribaga ta&#39;sir qiladi. Ba&#39;zi gaplar (masalan, tugma o&#39;lchami) ikkala tomonga ham tegishli bo&#39;lishi mumkin: bahsni rag&#39;batlantiring, mantiqiy asos bo&#39;lsa qabul qiling.</p><h3 id="o-rta-—-ilova-tahlili" tabindex="-1">O&#39;rta — Ilova tahlili <a class="header-anchor" href="#o-rta-—-ilova-tahlili" aria-label="Permalink to &quot;O&#39;rta — Ilova tahlili&quot;">​</a></h3><p>Telegram, Instagram yoki sevimli o&#39;yinni tanlang. Jadval to&#39;ldiring: 2 ta yaxshi UX nuqtasi, 1 ta yomon UX nuqtasi, 2 ta UI element (rang, shrift, ikon) va ular nima uchun mos tushgani. <strong>Kutiladigan natija:</strong> to&#39;ldirilgan jadval (daftar yoki skrinshot bilan). <strong>Yechim namunasi (Telegram):</strong></p><table tabindex="0"><thead><tr><th></th><th>Misol</th></tr></thead><tbody><tr><td>Yaxshi UX</td><td>Xabar yuborish 1 tugma; yozishmalar tez qidiriladi</td></tr><tr><td>Yomon UX</td><td>Sozlamalar ko&#39;p bo&#39;limli, kerakli narsani topish qiyin (o&#39;quvchi fikri bo&#39;lishi mumkin)</td></tr><tr><td>UI</td><td>Ko&#39;k asosiy rang va oq fon: sokin, ishonchli; yumaloq avatarlar</td></tr><tr><td>Aniq javob o&#39;quvchi tanlovga bog&#39;liq: mezon — tanlov asoslangan bo&#39;lsa bo&#39;ldi.</td><td></td></tr></tbody></table><h3 id="qiyin-—-bir-ux-ikki-ui" tabindex="-1">Qiyin — Bir UX, ikki UI <a class="header-anchor" href="#qiyin-—-bir-ux-ikki-ui" aria-label="Permalink to &quot;Qiyin — Bir UX, ikki UI&quot;">​</a></h3><p>Maktab oshxonasi uchun «Buyurtma» ekranini qog&#39;ozda 2 xil UI da chizing (telefon ramkasi). Qadamlar bir xil: taom tanlash → miqdor → «Buyurtma berish». Birida rang va shakl bir uslubda, ikkinchisi butunlay boshqa uslubda. Pastda: nima o&#39;zgardi (UI), nima o&#39;zgarmadi (UX)? <strong>Kutiladigan natija:</strong> 2 ta eskiz va 2–3 jumlalik izoh. <strong>Yechim:</strong> UI farqi: rang, shrift, tugma shakli, ikonlar. UX bir xil: qadamlar soni va tartibi. Kuchli o&#39;quvchi uchun: UX ni ham yaxshilash (masalan, «Oxirgi buyurtmani takrorlash» tugmasi).</p><h3 id="bonus" tabindex="-1">Bonus <a class="header-anchor" href="#bonus" aria-label="Permalink to &quot;Bonus&quot;">​</a></h3><p>UX/UI dizayner ish e&#39;loni (hh.uz, LinkedIn yoki Telegram kanal) toping. Qaysi talablar UX ga, qaysilari UI ga tegishli? <strong>Yechim:</strong> UX: tadqiqot, wireframe, test; UI: rang, tipografiya, dizayn tizimi, Figma. Haqiqiy e&#39;lon bo&#39;yicha tekshiring.</p>',10))]),i("div",U,[i("h2",f,[t(n,{name:"file-text"}),a[15]||(a[15]=l(" 5. Tezkor nazorat ",-1)),a[16]||(a[16]=i("a",{class:"header-anchor",href:"#_5-tezkor-nazorat","aria-label":'Permalink to "<Icon name="file-text" /> 5. Tezkor nazorat"'},"​",-1))]),a[17]||(a[17]=r("<ol><li>UX ning to&#39;liq nomi va ma&#39;nosi? <em>(User Experience, foydalanuvchi tajribasi.)</em></li><li>UI ning to&#39;liq nomi va ma&#39;nosi? <em>(User Interface, foydalanuvchi interfeysi: ko&#39;rinish va tuzilma.)</em></li><li>«Tugma rangi» UX ga tegishlimi yoki UI ga? <em>(UI.)</em></li><li>Chiroyli lekin foydalanib bo&#39;lmaydigan ilova qaysi qismi yomon? <em>(UX.)</em></li><li>UX/UI dizayner qanday mahsulotlar bilan ishlaydi? <em>(Veb-sayt, mobil ilova, dashboard, aqlli qurilma...)</em></li><li>Yaxshi UX/UI biznesga nima beradi? <em>(Mamnunlik, raqobatbardoshlik, brendga ishonch.)</em></li></ol>",1))]),i("div",z,[i("h2",p,[t(n,{name:"file-text"}),a[18]||(a[18]=l(" 6. Uyga vazifa ",-1)),a[19]||(a[19]=i("a",{class:"header-anchor",href:"#_6-uyga-vazifa","aria-label":'Permalink to "<Icon name="file-text" /> 6. Uyga vazifa"'},"​",-1))]),a[20]||(a[20]=i("p",null,[i("code",null,"uyga-vazifa.md"),l(" dagi 1-topshiriq (hafta uchun umumiy fayl, boshqa agent tayyorlaydi). Taklif: «O'zingiz kunda foydalanadigan 1 ta ilovada 1 ta yaxshi va 1 ta yomon UX nuqtasini toping, skrinshot yoki tavsif bilan» (20–25 daqiqa).")],-1))]),i("div",x,[i("h2",I,[t(n,{name:"file-text"}),a[21]||(a[21]=l(" 7. Mentor uchun eslatmalar ",-1)),a[22]||(a[22]=i("a",{class:"header-anchor",href:"#_7-mentor-uchun-eslatmalar","aria-label":'Permalink to "<Icon name="file-text" /> 7. Mentor uchun eslatmalar"'},"​",-1))]),a[23]||(a[23]=i("ul",null,[i("li",null,"Birinchi dars: o'quvchilar bir-birini tanimasligi mumkin, 2–3 daqiqa tanishuv qo'shing."),i("li",null,"Talab qilinadigan dastur yo'q; Figma keyingi hafta/bobda. Ro'yxatdan o'tish talab qilinsa, mentor oldindan tayyorlasin."),i("li",null,"2-darsga ko'prik: «Yaxshi UX ni nima yaratadi? Qaysi qoidalar bor? Bu 2-darsda».")],-1))])])}const S=o(h,[["render",c]]);export{A as __pageData,S as default};
